// Generated by scripts/build.mjs. Keep the original sw.js URL and scope.
const PREFIX = 'concursos:' + self.registration.scope + ':';
const CACHE = PREFIX + '0.33.2';
const ASSETS = [
  "./",
  "./index.html",
  "./concursos.css",
  "./icon-180.png",
  "./icon-192.png",
  "./icon-32.png",
  "./icon-512.png",
  "./icon-maskable-512.png",
  "./icon.svg",
  "./identity.css",
  "./manifest.webmanifest",
  "./mobile.css",
  "./src/app.js",
  "./src/appearance.js",
  "./src/bootstrap.js",
  "./src/catalog.js",
  "./src/contest-ui.js",
  "./src/domain.js",
  "./src/forms.js",
  "./src/gestures.js",
  "./src/history.js",
  "./src/import-ui.js",
  "./src/importing.js",
  "./src/legacy-actions.js",
  "./src/navigation.js",
  "./src/pwa.js",
  "./src/rendering.js",
  "./src/repository.js",
  "./src/settings.js",
  "./src/snapshots.js",
  "./src/state.js",
  "./src/study.js",
  "./src/sync/engine.js"
];
self.addEventListener('install', event => {
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(ASSETS)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', event => {
  event.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(key => (key.startsWith(PREFIX) && key !== CACHE) || key === 'organizador').map(key => caches.delete(key)))).then(() => self.clients.claim()));
});
self.addEventListener('fetch', event => {
  if (event.request.method !== 'GET' || new URL(event.request.url).origin !== self.location.origin) return;
  event.respondWith(fetch(event.request).then(response => {
    if (response.ok && response.type !== 'opaque') {
      const copy = response.clone();
      event.waitUntil(caches.open(CACHE).then(cache => cache.put(event.request, copy)).catch(() => {}));
    }
    return response;
  }).catch(async () => {
    const cache = await caches.open(CACHE);
    const saved = await cache.match(event.request);
    if (saved) return saved;
    if (event.request.mode === 'navigate') return (await cache.match('./index.html')) || Response.error();
    return Response.error();
  }));
});
